import{HostDocument}from'./host-document';import{DEFAULT_TONE}from'../../../../src/shared/settings/design-tone';
import{ToneStateSchema}from'../../../../src/shared/settings/design-tone';import{ToneSession}from'./tone-session';
import{encodeSelectionRaster}from'../../../../src/shared/patent/design-selection-raster';
export async function verifyTone(){
 const soft=document.createElement('canvas');soft.width=4;soft.height=1;const sc=soft.getContext('2d')!;sc.fillStyle='rgb(64,100,200)';sc.fillRect(0,0,4,1);
 const sd=new HostDocument({projectId:'tone-soft',width:4,height:1,layers:[{name:'Soft',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:soft}]});
 try{sd.select([[[[0,0],[4,0],[4,1],[0,1],[0,0]]]],'replace',{coverage:encodeSelectionRaster(4,1,new Uint8Array([0,128,255,0]))});const result=await sd.tonePixels({...DEFAULT_TONE,channel:'r',gamma:2});try{const values=result.canvas.getContext('2d')!.getImageData(0,0,4,1).data;if(values[0]!==64||values[4]!==96||values[8]!==128||values[9]!==100||values[10]!==200||values[11]!==255)throw Error('Soft mask/channel/alpha coupling failed');}finally{result.canvas.width=0;}sd.undo();sd.select(undefined,'replace');sd.crop({left:1,top:0,width:3,height:1},false);const adjusted=await sd.tonePixels({...DEFAULT_TONE,gamma:2});adjusted.canvas.width=0;sd.resizeCanvas(4,1,{horizontal:'right',vertical:'top'});const pixels=sd.canvas.getLayer(0).context.getImageData(0,0,4,1).data;if(pixels[0]!==64||pixels[4]!==128)throw Error('Off-canvas pixels lost or adjusted unexpectedly');}finally{sd.destroy();soft.width=0;}
 const large=document.createElement('canvas');large.width=1600;large.height=1200;const lc=large.getContext('2d')!;lc.fillStyle='rgb(64,64,64)';lc.fillRect(0,0,1600,1200);const ld=new HostDocument({projectId:'tone-large',width:1600,height:1200,layers:[{name:'Large',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:large}]});let ls:ToneSession;ls=new ToneSession(ld,{...DEFAULT_TONE,gamma:2},{changed(){},remember(){},release(){},finished(){ls.close();}});
 try{const identity=ld.contentIdentity();ls.start();for(const gamma of [1.2,1.5,2,3])ls.update({...DEFAULT_TONE,gamma});while(ls.state.busy)await new Promise(r=>setTimeout(r,1));if(ls.state.options.gamma!==3||!ls.state.canApply||ld.contentIdentity()!==identity)throw Error('Rapid previews stale or mutated source');const final=await ld.tonePixels({...DEFAULT_TONE,gamma:3},undefined,false);const a=document.createElement('canvas'),b=document.createElement('canvas');a.width=b.width=224;a.height=b.height=168;a.getContext('2d')!.drawImage(final.canvas,0,0,224,168);await new Promise<void>((resolve,reject)=>{const im=new Image();im.onload=()=>{b.getContext('2d')!.drawImage(im,0,0);if(a.toDataURL()!==b.toDataURL())reject(Error('Latest preview does not match final parameters'));else resolve();};im.onerror=()=>reject(Error('Invalid latest preview'));im.src=ls.state.after!;});a.width=b.width=final.canvas.width=0;ls.apply();ls.cancel();while(ls.state.busy)await new Promise(r=>setTimeout(r,1));if(ld.contentIdentity()!==identity)throw Error('Large apply cancellation changed source');}finally{ls.close();ld.destroy();large.width=large.height=0;}
 const noise=document.createElement('canvas');noise.width=noise.height=320;const ctx=noise.getContext('2d')!,data=ctx.createImageData(320,320);let seed=1;for(let i=0;i<data.data.length;i++){seed=(Math.imul(seed,1664525)+1013904223)|0;data.data[i]=i%4===3?255:seed>>>24;}ctx.putImageData(data,0,0);
 const noisy=new HostDocument({projectId:'tone-noise',width:320,height:320,layers:[{name:'Noise',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:noise}]});let session:ToneSession;let releases=0;session=new ToneSession(noisy,{...DEFAULT_TONE,gamma:2},{changed(){},remember(){},release(){releases++;},finished(){session.close();}});
 try{if(!ToneStateSchema.safeParse(session.state).success)throw Error('Noisy before preview exceeds protocol');session.start();while(session.state.busy)await new Promise(r=>setTimeout(r,1));if(!session.state.canApply||!ToneStateSchema.safeParse(session.state).success)throw Error('Noisy after preview invalid');const before=noisy.contentIdentity();session.apply();session.cancel();while(session.state.busy)await new Promise(r=>setTimeout(r,1));if(noisy.contentIdentity()!==before||releases!==1)throw Error('Apply cancellation changed source or leaked resources');}finally{session.close();noisy.destroy();noise.width=noise.height=0;}
 const check=(v:unknown,m:string)=>{if(!v)throw Error(m);},source=document.createElement('canvas');source.width=4;source.height=2;const x=source.getContext('2d')!;x.fillStyle='rgb(120,120,120)';x.fillRect(0,0,4,2);x.clearRect(3,0,1,1);
 const layer={name:'Tone',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over' as const,image:source};const d=new HostDocument({projectId:'tone',width:4,height:2,layers:[layer,{...layer,name:'hidden',isVisible:false}]});
 try{
 const id=d.canvas.getLayer(0).id;d.history.setActiveLayer(id);d.select([[[[0,0],[2,0],[2,2],[0,2],[0,0]]]],'replace');const before=d.contentIdentity(),selection=JSON.stringify(d.history.getComposed().selection),count=d.capture().history.totalActions;
 const options={...DEFAULT_TONE,mode:'threshold' as const};const preview=await d.tonePixels(options,undefined,false);check(preview.changed&&preview.histogram[120]===4,'Selection histogram incorrect');preview.canvas.width=0;check(before===d.contentIdentity(),'Preview mutated source');
 const result=await d.tonePixels(options);result.canvas.width=0;check(d.canvas.getLayer(0).context.getImageData(0,0,1,1).data[0]===0&&d.canvas.getLayer(0).context.getImageData(2,0,1,1).data[0]===120,'Threshold ignored selection');check(!d.canvas.getLayer(1).isVisible&&d.canvas.getLayer(1).context.getImageData(0,0,1,1).data[0]===120,'Other layer changed');check(d.capture().history.totalActions===count+1&&JSON.stringify(d.history.getComposed().selection)===selection,'History or selection lost');
 d.undo();check(d.contentIdentity()===before,'Undo failed');d.redo();const restored=await HostDocument.openProject(await d.exportProject());check(restored.canvas.getLayer(0).context.getImageData(0,0,1,1).data[0]===0,'Reopen failed');restored.destroy();d.undo();
 const abort=new AbortController();abort.abort();try{await d.tonePixels(options,abort.signal);throw Error('Abort accepted');}catch(e){check(e instanceof DOMException&&e.name==='AbortError','Cancellation failed');}check(d.contentIdentity()===before,'Cancel mutated image');
 const push=d.history.push.bind(d.history);d.history.push=()=>{throw Error('Rejected');};try{await d.tonePixels(options);}catch{}finally{d.history.push=push;}check(d.contentIdentity()===before,'Failed history changed image');
 d.setLayerLocks(id,{pixels:true});let rejected=false;try{await d.tonePixels(options);}catch{rejected=true;}check(rejected,'Locked pixels editable');d.setLayerLocks(id,{pixels:false});d.select(null,'replace');const tone=await d.tonePixels({...DEFAULT_TONE,gamma:2});check(tone.canvas.getContext('2d')!.getImageData(3,0,1,1).data[3]===0,'Transparency changed');tone.canvas.width=0;
 }finally{d.destroy();source.width=source.height=0;}
}
